85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
114	        if (normalizedTelephone == null) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
118	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        owner.setTelephone(normalizedTelephone);
123	        // Consolidated duplicate detection: all of the former separate telephone, email
124	        // and household checks are now expressed through the single derived identityKey
125	        // (telephone|email|householdId). Reject only when the new owner's WHOLE
126	        // identityKey equals an existing owner's. The household id is assigned later in
127	        // this method, so at this point the new owner's key carries an empty household
128	        // segment; two members of the same household with different telephones therefore
129	        // have different keys and are both allowed.
130	        String identityKey = owner.getIdentityKey();
131	        if (this.clinicService.findAllOwners().stream()
132	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
133	            return new ResponseEntity<>(HttpStatus.CONFLICT);
134	        }
135	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
136	            return new ResponseEntity<>(HttpStatus.CONFLICT);
137	        }
138	        LocalDate effectiveDate =
139	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
140	        LocalDate registrationDate = toBusinessDay(effectiveDate);
141	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
142	        if (ownersRegisteredToday >= 100) {
143	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
144	        }
145	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
146	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
147	        List<Owner> householdMembers =
148	            findHouseholdMembers(ownerFieldsDto.getLastName(), normalizedAddress);
149	        HttpHeaders headers = new HttpHeaders();
150	        owner.setRegistrationDate(registrationDate);
151	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
152	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
153	        owner.setBulkSignupWarning(bulkSignupWarning);
154	        if (sharesHousehold && !householdMembers.isEmpty()) {
155	            String householdId = householdId(owner.getLastName(), normalizedAddress);
156	            owner.setHouseholdId(householdId);
157	            owner.setHouseholdSize(householdMembers.size() + 1);
158	            for (Owner member : householdMembers) {
159	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
160	                    member.setHouseholdId(householdId);
161	                    this.clinicService.saveOwner(member);
162	                }
163	            }
164	        }
165	        this.clinicService.saveOwner(owner);
166	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
167	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
168	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
169	        headers.setLocation(UriComponentsBuilder.newInstance()
170	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
171	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
177	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
178	        if (currentOwner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
182	        if (normalizedTelephone == null) {
183	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	        }
185	        currentOwner.setAddress(ownerFieldsDto.getAddress());
186	        currentOwner.setCity(ownerFieldsDto.getCity());
187	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
188	        currentOwner.setLastName(ownerFieldsDto.getLastName());
189	        currentOwner.setTelephone(normalizedTelephone);
190	        currentOwner.setEmail(ownerFieldsDto.getEmail());
191	        this.clinicService.saveOwner(currentOwner);
192	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
193	    }
