215	        Pet pet = petMapper.toPet(petFieldsDto);
216	        owner.setId(ownerId);
217	        pet.setOwner(owner);
218	        pet.getType().setName(null);
219	        this.clinicService.savePet(pet);
220	        PetDto petDto = petMapper.toPetDto(pet);
221	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
222	            .buildAndExpand(pet.getId()).toUri());
