226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
229	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
230	        if (currentOwner != null) {
231	            Pet currentPet = this.clinicService.findPetById(petId);
232	            if (currentPet != null) {
233	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
234	                currentPet.setName(petFieldsDto.getName());
235	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
236	                this.clinicService.savePet(currentPet);
237	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
238	            }
239	        }
240	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	    }
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
246	        HttpHeaders headers = new HttpHeaders();
247	        Visit visit = visitMapper.toVisit(visitFieldsDto);
248	        Pet pet = new Pet();
249	        pet.setId(petId);
250	        visit.setPet(pet);
251	        this.clinicService.saveVisit(visit);
252	        VisitDto visitDto = visitMapper.toVisitDto(visit);
253	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
254	            .buildAndExpand(visit.getId()).toUri());
255	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
256	    }
257	
258	
259	    /**
260	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
261	     * stripped. When a leading {@code '+'} and country code are present they are kept;
262	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
263	     * is dropped from the national digits. The result must be a {@code '+'} followed
264	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
265	     * is returned to signal a bad request.
266	     */
267	    /**
268	     * Build the customer code for a newly created owner, formatted
269	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
270	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
271	     * the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to
272	     * one more than the number of owners already in that city.
273	     */
274	    private String nextCustomerCode(String city, String lastName) {
275	        String cityPrefix = prefixThree(city);
276	        String lastNamePrefix = prefixThree(lastName);
277	        String normalizedCity = normalizeForHousehold(city);
278	        int sequence = (int) this.clinicService.findAllOwners().stream()
279	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
280	            .count() + 1;
281	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
282	    }
283	
284	    /**
285	     * Count the existing owners whose city matches the given one, compared after
286	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
287	     * cap: a city that already holds this many owners is at capacity.
288	     */
289	    private long countOwnersInCity(String city) {
290	        String normalizedCity = normalizeForHousehold(city);
291	        return this.clinicService.findAllOwners().stream()
292	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
293	            .count();
294	    }
295	
296	    /**
297	     * Count the existing owners whose registration date falls on the given day. Used to
298	     * enforce the per-day create limit: once this many owners have been registered today,
299	     * the day is at capacity and further creates are rejected.
300	     */
301	    private long countOwnersRegisteredOn(LocalDate day) {
302	        return this.clinicService.findAllOwners().stream()
303	            .filter(existing -> day.equals(existing.getRegistrationDate()))
304	            .count();
305	    }
306	
307	    /**
308	     * Roll a registration date forward to the next business day: a date falling on a
309	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
310	     * returned unchanged.
311	     */
312	    private LocalDate toBusinessDay(LocalDate date) {
313	        DayOfWeek dayOfWeek = date.getDayOfWeek();
314	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
315	            return date.plusDays(8 - dayOfWeek.getValue());
316	        }
317	        return date;
318	    }
319	
320	    /** Upper-cased first three letters of {@code value} (fewer if shorter, empty if null). */
321	    private String prefixThree(String value) {
322	        String v = value == null ? "" : value;
323	        return v.substring(0, Math.min(3, v.length())).toUpperCase(Locale.ROOT);
324	    }
325	
326	    /**
327	     * Find the existing owners that already belong to the same household as the given
328	     * last name and address, i.e. those sharing both fields. Both are compared
329	     * case-insensitively after collapsing runs of whitespace to a single space and
330	     * trimming the ends.
331	     */
332	    private List<Owner> findHouseholdMembers(String lastName, String address) {
333	        String normalizedLastName = normalizeForHousehold(lastName);
334	        String normalizedAddress = normalizeForHousehold(address);
335	        return this.clinicService.findAllOwners().stream()
336	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
337	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
338	            .toList();
339	    }
340	
341	    /**
342	     * Count the existing owners that already share both the given first and last
343	     * name, compared case-insensitively. Used to populate an owner's namesake count
344	     * at creation time, reflecting how many owners with the same name existed before
345	     * this one was created.
346	     */
347	    private int countNamesakes(String firstName, String lastName) {
348	        String normalizedFirstName = normalizeName(firstName);
349	        String normalizedLastName = normalizeName(lastName);
350	        return (int) this.clinicService.findAllOwners().stream()
351	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
352	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
353	            .count();
354	    }
355	
356	    private String normalizeName(String value) {
357	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
358	    }
359	
360	    /**
361	     * Build a stable identifier shared by all owners of one household. It is derived
362	     * deterministically from the normalized last name and address, so every owner at
363	     * the same household resolves to the same value regardless of creation order.
364	     */
365	    private String householdId(String lastName, String address) {
366	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
367	        try {
368	            byte[] digest = MessageDigest.getInstance("SHA-256")
369	                .digest(key.getBytes(StandardCharsets.UTF_8));
370	            StringBuilder sb = new StringBuilder();
371	            for (int i = 0; i < 6; i++) {
372	                sb.append(String.format("%02X", digest[i]));
373	            }
374	            return "HH-" + sb;
375	        }
376	        catch (NoSuchAlgorithmException e) {
377	            throw new IllegalStateException(e);
378	        }
379	    }
380	
381	    private String normalizeForHousehold(String value) {
382	        if (value == null) {
383	            return "";
384	        }
385	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
386	    }
387	
388	    private String normalizeTelephone(String telephone) {
389	        if (telephone == null) {
390	            return null;
391	        }
392	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
393	        String digits;
394	        if (cleaned.startsWith("+")) {
395	            digits = cleaned.substring(1);
396	        } else {
397	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
398	            digits = "61" + national;
399	        }
400	        if (!digits.matches("[0-9]{8,15}")) {
401	            return null;
402	        }
403	        if (!hasValidNationalLength(digits)) {
404	            return null;
405	        }
406	        return "+" + digits;
407	    }
408	
409	    /**
410	     * Validate the national-number length of an E.164 number (the digits, without the
411	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
412	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
413	     * codes without a known rule are accepted as-is.
414	     */
415	    private boolean hasValidNationalLength(String digits) {
416	        if (digits.startsWith("61")) {
417	            return digits.length() - 2 == 9;
418	        }
419	        if (digits.startsWith("1")) {
420	            return digits.length() - 1 == 10;
421	        }
422	        return true;
423	    }
424	
425	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
426	    @Override
427	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
428	        Owner owner = this.clinicService.findOwnerById(ownerId);
429	        if (owner != null) {
430	            Pet pet = owner.getPet(petId);
431	            if (pet != null) {
432	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
433	            }
434	        }
435	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
436	    }
437	}
